import {workoutTypes,renderWorkout} from './workout-contract.js';
import {renderWeeklyReview,initWeeklyReview} from './weekly-review.js';
import {objectiveContext,objectiveDate,guideFor} from './goal-context.js';
import {configureAccountSync,resumeAccountSync} from './account-sync.js';
import {getActivePlan,allGeneratedSessions,visibleGeneratedSessions,sessionsForPlan,useOriginalPlan,exportPlanArchive,validatePlanArchive,mergePlanArchive,replaceOwnerArchive} from './active-plan.js';
import {renderProfile,initProfile,needsRegistration,renderAccountActions} from './profile.js';
import {PLAN,START,RACE,YARD,MILESTONES,SESSIONS,addDays} from './plan.js';
import {exportWorkoutFit,workoutRecipe,workoutInstructions} from './workout-fit.js';
const $=s=>document.querySelector(s);
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M8 2v4m8-4v4M3 10h18M4 4h16a1 1 0 0 1 1 1v15a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1',book:'M4 3h14a2 2 0 0 1 2 2v16H6a3 3 0 0 1-3-3V5a2 2 0 0 1 1-2Zm0 14h16M8 7h8m-8 4h5',flag:'M4 22V3m0 1c5-4 10 4 16 0v10c-6 4-11-4-16 0',leaf:'M20 3C9 1 2 6 4 14s13 8 16-11ZM4 20 15 9',arrow:'M5 12h14m-5-5 5 5-5 5',up:'M7 17 17 7M7 7h10v10',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-6h4l1 3 3 1 3 2-1 4 1 4-3 2-3 1-1 3h-4l-1-3-3-1-3-2 1-4-1-4 3-2 3-1Z',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',check:'m5 12 4 4 10-10',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l3 2',play:'m8 4 12 8-12 8Z',close:'m6 6 12 12M6 18 18 6',heart:'M20 5c-4-4-8 1-8 1S8 1 4 5s0 8 8 15c8-7 12-11 8-15Z',shoe:'m3 13 5-2 3-7 4 1-1 6 3 3 4 1v5H3Zm6-1 3 2m0-3 3 2',bottle:'M9 2h6v4l2 4v11H7V10l2-4Zm-2 9h10',strength:'M6 7v10m12-10v10M3 9v6m18-6v6M6 12h12',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 7v7m0-11v1',pause:'M8 4v16m8-16v16',cloud:'M6 18a5 5 0 1 1 1-10 6 6 0 0 1 12 2 4 4 0 0 1-1 8Z',left:'m15 6-6 6 6 6',right:'m9 6 6 6-6 6',reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',upload:'M12 17V3m-5 5 5-5 5 5M4 16v5h16v-5',edit:'m14 5 5 5M4 20l4-1L20 7l-4-4L4 15Z'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`}
const NAV=[['hoje','Hoje','home'],['plano','Plano','calendar'],['diario','Diário','book'],['prova','Objetivo','flag'],['guia','Guia','leaf']];
const CHECKLIST=['Conferir horário, local e regulamento com a organização','Tênis e meias já testados nos treinos','Água e recipientes para abastecimento','Carboidratos e alimentos já testados','Roupa extra e proteção para o clima','Cuidados para os pés e meias de reserva','Documento, inscrição e número de peito','Organizar o apoio e o material entre voltas'];
function knownSessions(){return [...SESSIONS,...allGeneratedSessions()];}
function diarySessions(){return [...SESSIONS,...visibleGeneratedSessions()];}
function scheduledSessions(){const active=getActivePlan();return active?sessionsForPlan(active):[];}

const KEY='dez-voltas-v1';
let storageAvailable=true;
let state={version:1,logs:{},checklist:{},timer:null};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.version===1){state=cleanState(saved);}localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;}
function cleanState(raw,extraSessions=[]){const sources=[...knownSessions(),...extraSessions];const clean={version:1,logs:{},checklist:{},timer:null};for(const s of sources){const x=raw.logs?.[s.id];if(!x)continue;const km=Number(x.km),minutes=Number(x.minutes),rpe=Number(x.rpe);if(!Number.isFinite(km)||km<0||(!s.generated&&km===0)||km>150||!Number.isFinite(minutes)||minutes<=0||minutes>1440||!Number.isInteger(rpe)||rpe<1||rpe>10)throw new Error('Registro com valores inválidos.');clean.logs[s.id]={km,minutes,rpe,pain:['none','mild','stop'].includes(x.pain)?x.pain:'none',notes:String(x.notes||'').slice(0,1500),date:s.date,updatedAt:typeof x.updatedAt==='string'?x.updatedAt:new Date().toISOString()};}for(let i=0;i<CHECKLIST.length;i++)clean.checklist[i]=raw.checklist?.[i]===true;const t=raw.timer;if(t&&sources.some(s=>s.id===t.id)&&Number.isFinite(t.elapsed)&&t.elapsed>=0&&Number.isFinite(t.startedAt)){clean.timer={id:t.id,elapsed:t.elapsed,running:t.running===true,startedAt:t.startedAt};}return clean;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;window.dispatchEvent(new Event('account-data-change'));return true;}catch{storageAvailable=false;toast('Sem acesso ao armazenamento. Exporte um backup para guardar os registros.');return false;}}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function number(n){return new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n)}
function today(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-');}
function fmtDate(iso,options={day:'2-digit',month:'short'}){return new Intl.DateTimeFormat('pt-BR',{...options,timeZone:'America/Sao_Paulo'}).format(new Date(iso+'T12:00:00Z'));}
const weekday=iso=>fmtDate(iso,{weekday:'short'}).replace('.','');
function daysBetween(a,b){return Math.round((Date.parse(b+'T00:00:00Z')-Date.parse(a+'T00:00:00Z'))/86400000)}
let dashboardWeek=Math.min(8,Math.max(1,Math.floor(daysBetween(START,today())/7)+1));
let selectedSession=knownSessions().find(s=>s.week===dashboardWeek&&s.date>=today())?.id||knownSessions().find(s=>s.week===dashboardWeek)?.id;
let route='hoje',installPrompt=null,toastTimeout,sessionId=null;

function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function heading(kicker,title,note='',action=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1></div>${action||`<p class="heading-note">${note}</p>`}</div>`}
function contours(){return `<svg class="contours" viewBox="0 0 400 400" fill="none" aria-hidden="true">${Array.from({length:12},(_,i)=>`<ellipse cx="220" cy="190" rx="${55+i*13}" ry="${85+i*15}" stroke="#b4d48c" stroke-width=".7" transform="rotate(${i*5},220,190)"/>`).join('')}</svg>`}
function savedObjective(){return objectiveContext(null,exportPlanArchive().owner,key=>localStorage.getItem(key));}
function currentObjective(){return objectiveContext(getActivePlan(),exportPlanArchive().owner,key=>localStorage.getItem(key));}
function currentPain(profile){return savedObjective()?.profile.pain??profile?.pain;}
function recoveryNotice(profile){return currentPain(profile)&&currentPain(profile)!=='none'?'<section class="notice">Você informou dor atual ou retorno de lesão. Revise sua preparação com um profissional antes de seguir com novas cargas.</section>':'';}
function emptyGoal(title='Seu próximo <em>passo.</em>'){return `${heading('UM OBJETIVO PARA VOCÊ',title)}<section class="panel empty-state"><h2>Defina seu próximo objetivo.</h2><p>Entre na sua conta e conte o que quer preparar, como está correndo e quais dias tem disponíveis. Hoje, Objetivo e Guia vão acompanhar essas informações.</p><a class="primary" href="#perfil">Configurar meu objetivo ${icon('arrow',14)}</a></section>`;}
function goalCountdown(p){const date=objectiveDate(p,today());return `<section class="countdown"><span class="eyebrow">${date.past?'DATA DO OBJETIVO':'CADA DIA CONTA'}</span><div class="countdown-number">${date.value}<span>${date.days===0?'':'dias'}</span></div><h3>${esc(p.details?.eventName||goalLabel(p))}</h3><p>${fmtDate(p.targetDate,{day:'numeric',month:'long',year:'numeric'})}${date.past?' · Revise seu próximo objetivo':''}</p></section>`;}
function renderHome(){const active=getActivePlan();if(active)return renderGeneratedHome();const context=currentObjective();if(!context)return emptyGoal();const p=context.profile;return `${heading('SEU OBJETIVO ESTÁ SALVO','Seu próximo <em>passo.</em>')}<div class="dashboard-top"><section class="hero"><span class="eyebrow">SEU PONTO DE PARTIDA</span><h2>${goalLabel(p)}</h2><p>Disponibilidade: ${p.days.length} dias por semana. Sua preparação começa com a base recente informada.</p><a class="primary lime" href="#perfil">Gerar ou revisar meu plano ${icon('arrow',14)}</a></section>${goalCountdown(p)}</div><section class="panel section-space"><h2>Nenhum plano em uso.</h2><p>Gere uma sugestão no Perfil, revise os treinos e escolha “Usar este plano” para preencher seu calendário.</p></section>`;}
function workoutCard(s){const log=state.logs[s.id];return `<article class="workout-card"><span class="eyebrow">${s.date===today()?'HOJE':s.date>today()?'NA SUA PROGRAMAÇÃO':'SESSÃO PROGRAMADA'} · ${fmtDate(s.date)}</span><div class="workout-distance">${number(s.km)} <span>km</span></div><h3>${s.title}</h3><div class="workout-meta"><span>${icon('heart',13)} Conversa confortável</span><span>${icon('shoe',13)} ${s.long?'Resistência':'Rodagem fácil'}</span></div>${log?`<div class="saved-label">${icon('check',15)} Registrado: ${number(log.km)} km · ${number(log.minutes)} min</div><br><button class="link-button" data-action="session" data-id="${s.id}">Ver ou editar registro ${icon('arrow',13)}</button>`:`<button class="primary" data-action="session" data-id="${s.id}">${icon('play',13)} Ver treino e registrar</button>`}</article>`}
function renderPlan(){if(getActivePlan())return renderWeeklyReview()+renderGeneratedPlan();return `${heading('UM PLANO PARA SUA ROTINA','Seu plano, <em>na prática.</em>')}<section class="panel empty-state"><h2>Nenhum plano em uso.</h2><p>Preencha seu objetivo no Perfil, gere uma sugestão e adote o plano depois de revisar. Os registros de preparações anteriores continuam no diário.</p><a class="primary" href="#perfil">Preparar meu plano ${icon('arrow',14)}</a></section>`;}

function goalLabel(p){return p.goal==='backyard'?`${number(p.target)} voltas backyard`:p.goal==='distance'?`${number(p.target)} km`:`${number(p.target)} minutos de corrida`;}
function generatedRow(s){return `<button class="run-row generated-run" data-action="session" data-id="${s.id}"><span><i class="check-circle ${state.logs[s.id]?'checked':''}">${state.logs[s.id]?icon('check',11):''}</i><span><small>${fmtDate(s.date,{weekday:'short',day:'numeric',month:'short'})}</small><strong>${esc(s.title)}</strong><small>${number(s.minutes)} min · RPE ${s.rpe}/10${s.workout?' · '+workoutTypes[s.workout.type]:s.long?' · Longo':''}</small></span></span><strong>${s.km>0?number(s.km)+' km':'Por tempo'} ${icon('right',12)}</strong></button>`;}
function renderGeneratedPlan(){const active=getActivePlan(),ss=sessionsForPlan(active),p=active.profile;return `${heading('SEU PLANO PERSONALIZADO','Do objetivo à <em>prática.</em>','','<button class="secondary" data-action="ics">'+icon('calendar',15)+' Exportar agenda</button>')}<section class="panel generated-summary"><span class="badge">Plano Gemini em uso</span><h2>${goalLabel(p)}</h2><p>${fmtDate(p.startDate)} → ${fmtDate(p.targetDate,{day:'numeric',month:'long',year:'numeric'})}</p><p>${esc(active.plan.summary)}</p><div class="notice"><strong>Avaliação da meta</strong><p>${esc(active.plan.feasibility)}</p></div>${active.plan.warnings.length?`<ul>${active.plan.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</section><div class="week-grid">${active.plan.weeks.map((w,i)=>{const runs=ss.filter(s=>s.week===i+1);return `<section class="week-card"><div class="week-head"><div><span class="eyebrow muted">SEMANA ${i+1} · ${fmtDate(w.start)}</span><h3>${runs.length} treino${runs.length===1?'':'s'}</h3></div><div class="week-km">${number(w.totalKm)}<span> km</span></div></div>${runs.map(generatedRow).join('')||'<p>Descanso e recuperação nesta semana.</p>'}<p>${esc(w.focus)}</p></section>`;}).join('')}</div><div class="notice">O calendário detalha somente este bloco inicial. As fases abaixo orientam o restante da preparação; reavalie o próximo bloco por volta de ${fmtDate(active.plan.reviewDate)} com base nos treinos realizados.</div><div class="section-space panel-top"><h2>As fases até o objetivo</h2><span class="badge neutral">A revisar pela recuperação</span></div><div class="timeline">${active.plan.phases.map(x=>`<section class="timeline-item"><span class="eyebrow muted">${fmtDate(x.start)} — ${fmtDate(x.end)}</span><h3>${esc(x.title)}</h3><p>${esc(x.focus)}</p></section>`).join('')}</div><div class="profile-buttons"><a class="primary" href="#perfil">Revisar objetivo ou gerar outra sugestão</a><button class="secondary" data-action="original-plan">Desativar plano atual</button></div><p class="field-help">Seu histórico anterior permanece no diário. O plano e os registros têm uma cópia local e são sincronizados quando você está conectado à conta. O backup inclui os planos adotados.</p>`;}
function renderGeneratedHome(){
 const active=getActivePlan(),p=active.profile,ss=sessionsForPlan(active),day=today(),onDay=ss.filter(s=>s.date===day),future=ss.find(s=>s.date>day&&!state.logs[s.id]),done=ss.filter(s=>state.logs[s.id]);
 const km=done.reduce((n,s)=>n+state.logs[s.id].km,0),minutes=done.reduce((n,s)=>n+state.logs[s.id].minutes,0),missed=ss.filter(s=>s.date<day&&!state.logs[s.id]).length;
 const review=day>=active.plan.reviewDate,past=day>p.targetDate,goalToday=day===p.targetDate;
 const focus=goalToday?'Hoje é o dia do seu objetivo':past?'Revise seu próximo objetivo':onDay.length?'Seu treino de hoje':future?'Sua próxima sessão':review?'Hora de revisar o próximo bloco':'Seu calendário';
 const sessions=onDay.length?onDay:[...(future?[future]:[])];
 return `${heading('SEU PLANO EM MOVIMENTO','Seu próximo <em>passo.</em>')}${recoveryNotice(p)}<div class="dashboard-top"><section class="hero"><span class="eyebrow">SEU PLANO PERSONALIZADO</span><h2>${goalLabel(p)}</h2><p>${esc(p.details?.eventName||'Consistência para o seu objetivo')} · ${p.days.length} dias disponíveis por semana</p><a class="primary lime" href="#plano">Abrir meu plano ${icon('arrow',14)}</a></section>${goalCountdown(p)}</div><div class="dashboard-grid"><section class="panel"><h2>${focus}</h2>${goalToday?'<p>Consulte as informações do objetivo e sua estratégia de execução. A conclusão não é registrada automaticamente.</p><a class="link-button" href="#prova">Ver meu objetivo</a>':past?'<p>A data do objetivo passou. Revise os próximos passos considerando o que realizou e como está se recuperando.</p>':sessions.length?sessions.map(generatedRow).join(''):review?'<p>O bloco detalhado chegou ao fim. Revise a próxima etapa com base no que conseguiu realizar e na sua recuperação.</p>':'<p>Não há corrida programada para hoje. Respeite a recuperação e consulte seu calendário.</p>'}${!onDay.length&&future?'<p class="field-help">Hoje não há corrida no calendário. A sessão acima é a próxima programada.</p>':''}${onDay.some(s=>state.logs[s.id])?'<p class="notice">Treino de hoje registrado. Você pode abrir a sessão para consultar ou editar o registro.</p>':''}${missed?`<p class="field-help">${missed} sessão(ões) passada(s) sem registro. Registre apenas o que realizou; evite compensar acumulando sessões.</p>`:''}${review||past?'<a class="link-button" href="#perfil">Revisar objetivo e preparação</a>':''}</section><section class="panel"><h2>Seu bloco detalhado</h2><div class="big-number">${number(p.goal==='time'?minutes:km)} <span>${p.goal==='time'?'minutos':'km'} registrados</span></div><p>${done.length} de ${ss.length} sessões registradas neste bloco.</p><p class="field-help">Esses registros acompanham o treino realizado; não confirmam a conclusão do objetivo final.</p><a class="link-button" href="#diario">Ver meu diário ${icon('arrow',14)}</a></section></div>`;
}

function renderDiary(){const done=diarySessions().filter(s=>state.logs[s.id]).sort((a,b)=>b.date.localeCompare(a.date));const total=done.reduce((a,s)=>a+state.logs[s.id].km,0),minutes=done.reduce((a,s)=>a+state.logs[s.id].minutes,0);return `${heading('CADA TREINO TEM UMA HISTÓRIA','Seu diário de <em>movimento.</em>','O que você fez e como se sentiu. Só entram aqui os treinos registrados.')}<div class="stats-row"><div class="stat-box"><span class="eyebrow">TREINOS REGISTRADOS</span><div class="big-number">${done.length}</div></div><div class="stat-box"><span class="eyebrow">DISTÂNCIA REALIZADA</span><div class="big-number">${number(total)} <span>km</span></div></div><div class="stat-box"><span class="eyebrow">TEMPO EM MOVIMENTO</span><div class="big-number">${number(minutes/60)} <span>h</span></div></div></div>${done.length?`<div class="panel-top"><h2>Seus registros</h2><button class="link-button" data-action="export-csv">Exportar CSV ${icon('download',13)}</button></div><div class="log-list">${done.map(s=>{const l=state.logs[s.id];return `<article class="log-card"><div><span class="eyebrow muted">${fmtDate(s.date,{weekday:'short',day:'numeric',month:'short'})} · SEMANA ${s.week}</span><h3 style="margin-top:8px">${esc(s.title)}</h3><div class="log-data"><span>${number(l.km)} km</span><span>${number(l.minutes)} min</span><span>Esforço ${l.rpe}/10</span></div>${l.pain!=='none'?`<p style="color:#a46b36">${l.pain==='mild'?'Incômodo registrado: observe antes de avançar.':'Dor que pediu interrupção: avalie antes de retomar.'}</p>`:''}${l.notes?`<p class="log-note">${esc(l.notes)}</p>`:''}</div><button class="edit-link" data-action="session" data-id="${s.id}" aria-label="Editar treino de ${fmtDate(s.date)}">${icon('edit',17)}</button></article>`}).join('')}</div>`:`<div class="empty-state">${icon('book',35)}<h2>Seu primeiro registro está por vir.</h2><p>Depois de correr, guarde a distância, o tempo e a sensação do treino. A consistência aparece um dia de cada vez.</p><a class="primary" href="#plano">Escolher um treino ${icon('arrow',14)}</a></div>`}<div class="notice"><strong>Diário e cópia local.</strong> Ao entrar na conta, os registros são sincronizados com o Supabase. Sem internet, ficam neste aparelho até o próximo envio. Confira o estado da sincronização no Perfil.</div>`}
function renderRace(){
 const context=currentObjective();if(!context)return emptyGoal('Seu próximo <em>objetivo.</em>');const p=context.profile,d=p.details||{},date=objectiveDate(p,today());
 const terrain={road:'Asfalto / estrada',trail:'Trilha',mixed:'Misto',treadmill:'Esteira',unspecified:'Não informado'};
 const facts=p.goal==='backyard'?`<p>No formato backyard padrão, cada volta tem <strong>6,7056 km</strong> e a largada se repete a cada hora. Sua meta é ${number(p.target)} volta(s), equivalente a ${number(p.target*YARD)} km.</p><p>A volta precisa terminar antes da largada seguinte. O tempo restante serve para pausa e organização. Confirme percurso, horários e regras com a organização.</p><a class="link-button" href="https://bigsbackyardultra.com/rules/" target="_blank" rel="noopener noreferrer">Regras do formato ${icon('up',13)}</a>`:p.goal==='distance'?`<p>Seu objetivo é completar <strong>${number(p.target)} km</strong>. A preparação e o esforço das sessões devem respeitar sua base recente e sua disponibilidade.</p>${d.finishMinutes?`<p>Tempo desejado: <strong>${number(d.finishMinutes)} minutos</strong>. É uma referência para avaliar a meta; não é um ritmo prescrito para todos os treinos.</p>`:''}`:`<p>Seu objetivo é correr por <strong>${number(p.target)} minutos</strong>. As durações e os intervalos de caminhada de cada treino continuam sendo definidos no plano.</p><p>Essa meta não pressupõe uma distância nem um ritmo fixo.</p>`;
 const checks=[p.goal==='time'?'Definir horário, local seguro e forma de acompanhar o tempo':'Conferir horário, percurso e regulamento com a organização',...CHECKLIST.slice(1,6),d.eventName?'Documento, inscrição e identificação da prova':'Celular carregado e contato para emergência',p.goal==='backyard'?'Organizar apoio e material para as pausas entre voltas':'Planejar percurso, retorno e pontos de apoio'];
 return `${heading('O SEU PRÓXIMO DESAFIO','Seu objetivo, <em>do seu jeito.</em>')}<div class="race-layout"><section class="hero race-large"><span class="eyebrow">${fmtDate(p.targetDate,{day:'numeric',month:'long',year:'numeric'})}</span><h2>${esc(d.eventName||goalLabel(p))}</h2><p>${goalLabel(p)} · ${date.days===0?'O dia do seu objetivo':date.past?'A data passou; revise seus próximos passos':'Preparação orientada pela sua base atual'}</p><div class="hero-footer"><div><strong>${date.value}</strong><span>${date.label.toUpperCase()}</span></div><div><strong>${p.days.length}</strong><span>DIAS DISPONÍVEIS / SEMANA</span></div>${p.goal==='backyard'?`<div><strong>${number(p.target*YARD)} km</strong><span>DISTÂNCIA DA META</span></div>`:''}</div>${contours()}</section><section class="panel"><h2>${p.goal==='backyard'?'Entenda o formato':'O que você está preparando'}</h2>${facts}<p><strong>Terreno:</strong> ${terrain[d.terrain]||'Não informado'}</p>${d.elevationM!==null&&d.elevationM!==undefined?`<p><strong>Subida acumulada informada:</strong> ${number(d.elevationM)} m</p>`:''}<p class="field-help">Dados do ${context.source==='active'?'plano em uso':'seu cadastro'}. Confirme as informações da prova com a organização.</p><a class="link-button" href="#perfil">Revisar meus dados</a></section>${p.goal==='backyard'?`<section class="panel"><h2>Ensaie o tempo da volta</h2><label class="field">Tempo por volta (minutos)<input id="lap-minutes" type="number" value="52" min="1" max="59.9" step="0.1" inputmode="decimal"></label><div id="lap-result" class="calc-result"></div><p class="field-help">Referência aritmética, sem prescrever ritmo. Terreno, clima e esforço mudam a execução.</p></section>`:''}<section class="panel"><div class="panel-top"><h2>Seu checklist</h2><span class="badge neutral" id="checklist-count"></span></div><div class="checklist">${checks.map((text,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${state.checklist[i]?'checked':''}><span>${esc(text)}</span></label>`).join('')}</div><p class="field-help">Confira os itens novamente ao mudar objetivo, data ou percurso.</p></section></div>`;
}
function renderGuide(){const context=currentObjective(),p=context?.profile,active=getActivePlan();return `${heading('ORIENTAÇÕES PARA SUA PREPARAÇÃO','Cuide do <em>caminho.</em>')}${p?`<section class="notice"><strong>${goalLabel(p)}</strong> · ${p.days.length} dias disponíveis por semana · base informada de ${number(p.weeklyKm)} km/semana. Orientações do ${context.source==='active'?'plano em uso':'cadastro'}.</section>`:'<section class="notice">Estas são orientações gerais. <a href="#perfil">Defina seu objetivo</a> para contextualizar sua preparação.</section>'}<div class="guide-grid">${guideFor(p?{...p,pain:currentPain(p)}:null,active).map(card=>`<section class="guide-card">${icon(card.icon)}<h2>${esc(card.title)}</h2>${card.paragraphs.map(text=>`<p>${esc(text)}</p>`).join('')}</section>`).join('')}<section class="guide-card">${icon('download')}<h2>Opcional: Amazfit Active 2 e Zepp</h2><p>Se você usa esse relógio, pode consultar um roteiro para configurar o treino manualmente no Zepp. A compatibilidade depende do dispositivo e da versão do aplicativo.</p><button class="secondary" data-action="zepp-help">Consultar roteiro de treino</button></section></div>`;}
function render(){const focused=document.activeElement;const restoreFocus=focused?.closest?.('#weekly-checkin')?{name:focused.name,value:focused.value,start:focused.selectionStart,end:focused.selectionEnd}:null;const accountActions=document.querySelector('#account-actions');if(accountActions)accountActions.innerHTML=renderAccountActions();const mini=document.querySelector('.race-mini'),context=currentObjective();if(mini)mini.innerHTML=context?`<span class="eyebrow">O SEU OBJETIVO</span><strong>${goalLabel(context.profile)}</strong><span>${fmtDate(context.profile.targetDate,{day:'numeric',month:'long',year:'numeric'})}</span>`:'<span class="eyebrow">O SEU CAMINHO</span><strong>Seu próximo desafio.</strong><a href="#perfil">Definir meu objetivo</a>';route=needsRegistration()?'perfil':location.hash.slice(1)||'hoje';if(route!=='perfil'&&!NAV.some(x=>x[0]===route))route='hoje';document.title=`${route==='perfil'?'Meu objetivo':NAV.find(x=>x[0]===route)[1]} · Dez Voltas`;const nav=NAV.map(([id,label,ic])=>`<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic,19)}<span>${label}</span></a>`).join('');$('.desktop-nav').innerHTML=nav;$('.mobile-nav').innerHTML=nav;$('#main').innerHTML=({perfil:renderProfile,hoje:renderHome,plano:renderPlan,diario:renderDiary,prova:renderRace,guia:renderGuide}[route])();if(restoreFocus){const candidates=document.querySelectorAll('#weekly-checkin [name]');const next=[...candidates].find(x=>x.name===restoreFocus.name&&(x.name!=='days'||x.value===restoreFocus.value));if(next&&!next.disabled){next.focus({preventScroll:true});if(typeof restoreFocus.start==='number'&&next.setSelectionRange)next.setSelectionRange(restoreFocus.start,restoreFocus.end);}}if(route==='prova'){updateLap();updateChecklist();}}
function openSession(id){const s=knownSessions().find(x=>x.id===id);if(!s)return;sessionId=id;const l=state.logs[id];$('#session-content').innerHTML=`<div class="modal-inner"><div class="modal-top"><span class="eyebrow">SEMANA ${s.week} · ${fmtDate(s.date,{weekday:'short',day:'numeric',month:'long'})}</span><button class="icon-button" data-action="close-session" aria-label="Fechar treino">${icon('close',17)}</button></div><h2>${esc(s.title)}</h2><div class="session-summary"><span><strong>${s.km} km</strong> planejados</span><span>${s.generated?`${number(s.minutes)} min · RPE ${s.rpe}/10`:'Conversa confortável'}</span></div><button type="button" class="secondary full zepp-session-button" ${s.km>0||s.workout?'':'disabled title="Defina uma distância para preparar o modelo no Zepp"'} data-action="zepp" data-id="${s.id}">${icon('download',16)} Preparar treino para o Zepp <span>Configuração manual</span></button>${s.generated?`<div class="notice generated-instructions"><strong>Orientações do seu plano</strong><p>${esc(s.instructions)}</p>${renderWorkout(s.workout)}</div>`:`<div class="session-steps"><div><b>1</b><span><strong>Aqueça.</strong> Caminhe ou trote muito leve por 5–8 minutos.</span></div><div><b>2</b><span><strong>${s.km} km em esforço fácil.</strong> ${s.long?'Priorize conforto e resistência. Caminhada planejada pode entrar.':'Mantenha a conversa em frases completas. Caminhe se precisar.'}</span></div><div><b>3</b><span><strong>Desacelere e registre.</strong> Caminhe alguns minutos e observe como se sente.</span></div></div><p class="field-help">O aquecimento também soma carga e pode ser caminhando. ${s.km>=10?'Se passar de 75–90 minutos, pratique alimentação já testada.':''}</p>`}<section class="timer-section"><span class="eyebrow">CRONÔMETRO OPCIONAL · SEM GPS</span><div class="timer-digits" id="timer-display">00:00:00</div><div class="timer-controls"><button class="primary lime" data-action="timer-toggle" id="timer-toggle">Iniciar</button><button class="secondary" data-action="timer-use">Usar no registro</button></div><p class="timer-note">Conta o tempo decorrido, inclusive com a tela apagada. Não emite alertas em segundo plano. Pause ao terminar.</p></section><div class="form-divider"></div><h3>${l?'Editar seu registro':'Como foi o treino?'}</h3><p class="field-help">Preencha o que realmente realizou. A data do registro corresponde à sessão selecionada.</p><form id="log-form"><div class="form-row"><label class="field">Distância realizada (km)<input name="km" type="number" inputmode="decimal" min="${s.generated?0:0.1}" max="150" step="0.1" value="${l?.km??s.km}" required></label><label class="field">Duração (minutos)<input name="minutes" id="duration-field" type="number" inputmode="decimal" min="0.1" max="1440" step="0.1" value="${l?.minutes??''}" placeholder="Ex.: 40" required></label></div><div class="form-row"><label class="field">Esforço percebido<select name="rpe" required><option value="">Selecione</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${l?.rpe===i+1?'selected':''}>${i+1} / 10${i===0?' · muito fácil':i===9?' · máximo':''}</option>`).join('')}</select></label><label class="field">Dor ou incômodo<select name="pain"><option value="none" ${l?.pain==='none'?'selected':''}>Sem dor</option><option value="mild" ${l?.pain==='mild'?'selected':''}>Incômodo leve</option><option value="stop" ${l?.pain==='stop'?'selected':''}>Dor que pediu parar</option></select></label></div><label class="field">Sua observação<textarea name="notes" maxlength="1500" placeholder="Como estavam as pernas, a respiração e a disposição?">${esc(l?.notes||'')}</textarea></label><div class="feedback" id="log-feedback" role="alert"></div><div class="form-actions"><button class="secondary" type="button" data-action="close-session">Voltar</button><button class="primary" type="submit">${icon('check',15)} ${l?'Salvar alterações':'Salvar treino'}</button></div></form></div>`;$('#session-dialog').showModal();updateTimer();}
function timerElapsed(){const t=state.timer;if(!t)return 0;return t.elapsed+(t.running?Math.max(0,Date.now()-t.startedAt):0)}
function updateTimer(){if(!$('#session-dialog').open||!sessionId)return;const t=state.timer?.id===sessionId?state.timer:null;const ms=t?timerElapsed():0;const secs=Math.floor(ms/1000);$('#timer-display').textContent=[Math.floor(secs/3600),Math.floor(secs/60)%60,secs%60].map(n=>String(n).padStart(2,'0')).join(':');$('#timer-toggle').textContent=t?.running?'Pausar':ms>0?'Continuar':'Iniciar';}
function toggleTimer(){if(state.timer&&state.timer.id!==sessionId&&state.timer.running){toast('Há outro treino com cronômetro ativo. Pause-o antes de iniciar este.');return;}if(!state.timer||state.timer.id!==sessionId)state.timer={id:sessionId,elapsed:0,running:false,startedAt:Date.now()};const t=state.timer;if(t.running){t.elapsed=timerElapsed();t.running=false;}else{t.startedAt=Date.now();t.running=true;}save();updateTimer();}
function openInfo(title,body){$('#info-content').innerHTML=`<div class="modal-inner"><div class="modal-top"><h2 class="no-margin">${title}</h2><button class="icon-button" data-action="close-info" aria-label="Fechar">${icon('close',17)}</button></div>${body}</div>`;if(!$('#info-dialog').open)$('#info-dialog').showModal();}
function settings(){openInfo('Seu app, seus dados.',`<p class="storage-message ${!storageAvailable?'storage-error':''}">${storageAvailable?'Os registros ficam salvos neste navegador.':'O armazenamento está indisponível.'} Ao entrar na conta, perfil, planos e diário são sincronizados. Confira o estado no Perfil antes de trocar de aparelho ou limpar o navegador. Alterações offline só ficam protegidas na nuvem após o envio; mantenha backups.</p><div class="data-actions"><button class="secondary" data-action="export-json">${icon('download',17)} Baixar backup dos registros (JSON)</button><button class="secondary" data-action="import-json">${icon('upload',17)} Restaurar backup</button><button class="secondary" data-action="export-csv">${icon('book',17)} Exportar diário (CSV)</button><button class="secondary" data-action="ics">${icon('calendar',17)} Exportar treinos para calendário (.ics)</button><button class="secondary" data-action="zepp-help">${icon('shoe',17)} Active 2 e Zepp · modelo de treino</button><button class="primary" data-action="install">${icon('download',17)} Instalar no celular</button></div><p class="field-help" style="margin-top:20px">O plano fica disponível offline após o primeiro acesso e a preparação do cache. O acesso inicial ao site privado precisa de internet e da sua conta. Os links externos precisam de conexão.</p>`)}
async function install(){if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;return;}const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;if(standalone){openInfo('App já aberto.',`<p class="install-instructions">Você está usando o Dez Voltas no modo de aplicativo. Acesse seus treinos pela tela inicial do celular.</p>`);return;}openInfo('Leve o treino com você.',`<div class="install-instructions"><p><strong>iPhone / iPad</strong></p><ol><li>Abra este endereço no <strong>Safari</strong> e entre na sua conta, se solicitado.</li><li>Toque em <strong>Compartilhar</strong>.</li><li>Escolha <strong>Adicionar à Tela de Início</strong>.</li></ol><p><strong>Android</strong></p><ol><li>Abra o endereço no <strong>Chrome</strong>.</li><li>Toque no menu <strong>⋮</strong>.</li><li>Escolha <strong>Instalar app</strong> ou <strong>Adicionar à tela inicial</strong>.</li></ol><p class="small">Depois do primeiro carregamento, aguarde a indicação “Plano disponível offline”. As opções variam conforme o navegador.</p></div>`)}
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function exportJSON(){download(JSON.stringify({...state,generatedPlans:exportPlanArchive(),exportedAt:new Date().toISOString(),app:'dez-voltas'},null,2),'dez-voltas-backup-'+today()+'.json','application/json');toast('Backup preparado. Guarde o arquivo em um lugar seguro.');}
function exportCSV(){const rows=[['Data','Semana','Treino','Km planejados','Km realizados','Minutos','Esforço 1–10','Dor','Observações'],...diarySessions().filter(s=>state.logs[s.id]).map(s=>{const l=state.logs[s.id];return [s.date,s.week,s.title,s.km,l.km,l.minutes,l.rpe,l.pain,l.notes]})];const csv=rows.map(r=>r.map(x=>{let v=String(x??'');if(/^[=+@\-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}).join(';')).join('\r\n');download('\uFEFF'+csv,'dez-voltas-diario-'+today()+'.csv','text/csv;charset=utf-8');}
function icsText(value){return String(value).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function exportICS(){if(!scheduledSessions().length){toast('Adote um plano no Perfil antes de exportar a agenda.');return;}const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dez Voltas//Treinos//PT-BR','CALSCALE:GREGORIAN','X-WR-CALNAME:Dez Voltas — treinos'];for(const s of scheduledSessions())lines.push('BEGIN:VEVENT',`UID:${s.id}-20261026@dezvoltas.local`,`DTSTAMP:${stamp}`,`DTSTART;VALUE=DATE:${s.date.replaceAll('-','')}`,`DTEND;VALUE=DATE:${addDays(s.date,1).replaceAll('-','')}`,`SUMMARY:${s.km} km — ${icsText(s.title)}`,`DESCRIPTION:${icsText(s.generated?`Semana ${s.week}. ${s.minutes} min. RPE ${s.rpe}/10. ${s.instructions}`:`Semana ${s.week}. Esforço confortável e conversa em frases completas. Volume ajustável conforme recuperação.`)}`,`END:VEVENT`);lines.push('END:VCALENDAR');download(lines.join('\r\n')+'\r\n','dez-voltas-treinos.ics','text/calendar;charset=utf-8');toast(`Agenda preparada com ${scheduledSessions().length} treinos de dia inteiro.`);}
function updateLap(){if(currentObjective()?.profile.goal!=='backyard')return;const input=$('#lap-minutes');if(!input)return;const m=Number(input.value),out=$('#lap-result');if(!Number.isFinite(m)||m<=0||m>=60){out.innerHTML='<span>Informe um tempo maior que zero e menor que 60 minutos.</span>';return;}const sec=Math.round(m/YARD*60),rest=60-m;out.innerHTML=`<div><strong>${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}</strong><span>min/km de média na volta</span></div><div><strong>${number(rest)} min</strong><span>até a próxima largada</span></div>`;}
function updateChecklist(){const el=$('#checklist-count');if(el)el.textContent=`${Object.values(state.checklist).filter(Boolean).length}/${CHECKLIST.length}`;}
function connection(){const online=navigator.onLine;$('#connection').classList.toggle('is-offline',!online);$('#connection span').textContent=online?'Online':'Offline';}

let zeppSessionId=null;
function openZepp(id){
 const session=diarySessions().find(s=>s.id===id);if(!session)return;zeppSessionId=id;const selectable=[...scheduledSessions()];if(!selectable.some(s=>s.id===id))selectable.push(session);
 const shareAvailable=typeof navigator.share==='function'&&typeof navigator.canShare==='function';
 openInfo('Treino no seu Active 2.',`<span class="badge">Active 2 + iPhone · configuração manual</span><p class="modal-intro">Prepare as etapas para criar um <strong>modelo de treino no Zepp</strong>. Depois de salvar e sincronizar o modelo pelo Zepp, selecione-o no relógio para correr.</p><p class="zepp-compat">Este roteiro orienta a configuração manual no Zepp. A disponibilidade do envio depende do relógio e do aplicativo; copiar o texto ou importar um FIT não confirma a sincronização.</p><label class="field">Sessão planejada<select id="zepp-select">${selectable.map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${fmtDate(s.date)} · Semana ${s.week} · ${s.km} km</option>`).join('')}</select></label><div id="zepp-preview" class="zepp-preview" aria-live="polite"></div><div class="form-actions zepp-actions"><button class="primary" data-action="zepp-copy">${icon('book',16)} Copiar etapas</button><button class="secondary" data-action="zepp-text">${icon('download',16)} Baixar roteiro (.txt)</button></div><p id="zepp-status" class="field-help" role="status">Use estas etapas para criar o modelo no Zepp. A preparação do roteiro não envia o treino ao relógio.</p><details class="zepp-details"><summary>Ajustar aquecimento e desaquecimento</summary><div class="form-row"><label class="field">Aquecimento (min)<input id="zepp-warmup" type="number" inputmode="numeric" min="0" max="15" step="1" value="5"></label><label class="field">Desaquecimento (min)<input id="zepp-cooldown" type="number" inputmode="numeric" min="0" max="15" step="1" value="5"></label></div><p class="field-help">Use zero para omitir uma etapa. A distância do plano corresponde à etapa principal; o tempo adicional também soma carga.</p></details><details class="zepp-details" open><summary>Configurar o modelo no Zepp</summary><ol class="zepp-instructions"><li>No Zepp do iPhone, abra <strong>Treino → Mais → Modelo de treino</strong> (Training Template). Os nomes dos menus podem variar conforme a versão.</li><li>Crie um modelo de <strong>corrida ao ar livre</strong>. Configure as etapas exibidas acima: aquecimento por tempo, corrida pela distância do plano e desaquecimento por tempo. Use alvo livre, se disponível.</li><li>Salve o modelo e use <strong>Sincronizar com o relógio</strong> no Zepp, com o Active 2 conectado.</li><li>No relógio, selecione Corrida ao ar livre → Treino → Modelo de treino. Escolha o modelo e inicie a sessão na data prevista no nosso calendário.</li></ol><p class="field-help">Modelos de mesma distância podem ser reutilizados, desde que as outras etapas sejam iguais. Copiar o texto ajuda a consultar as etapas; o Zepp exige configurar os campos do modelo manualmente.</p></details><details class="zepp-details"><summary>Exportar arquivo FIT</summary><p class="small muted">O FIT contém as mesmas etapas estruturadas e pode ser importado no editor ou biblioteca do Intervals.icu. Na conexão que você tem hoje, essa importação <strong>não envia treinos planejados ao Active 2</strong>.</p><div class="form-actions"><button class="secondary" data-action="zepp-download">${icon('download',15)} Baixar FIT</button>${shareAvailable?`<button class="secondary" data-action="zepp-share">${icon('up',15)} Compartilhar FIT</button>`:''}</div><a class="link-button" href="https://forum.intervals.icu/t/import-and-download-workout-and-activity-fit-files/19295" target="_blank" rel="noopener noreferrer">Sobre importar treinos FIT ${icon('up',12)}</a></details><div class="zepp-sources"><a href="https://in.amazfit.com/pages/faq/how-do-i-use-the-training-template-feature-on-my-amazfit-active-2" target="_blank" rel="noopener noreferrer">Ajuda oficial: modelos no Active 2</a></div>`);
 updateZeppPreview();
}
function zeppSelection(){const session=knownSessions().find(s=>s.id===zeppSessionId);const warmup=$('#zepp-warmup'),cooldown=$('#zepp-cooldown');if(!session||warmup.value===''||cooldown.value==='')throw new Error('Preencha os minutos de aquecimento e desaquecimento.');const options={warmupMinutes:Number(warmup.value),cooldownMinutes:Number(cooldown.value)};return {session,options,recipe:workoutRecipe(session,options)};}
function updateZeppPreview(){try{const {recipe,session}=zeppSelection();$('#zepp-warmup').disabled=!!session.workout;$('#zepp-cooldown').disabled=!!session.workout;$('#zepp-preview').innerHTML=`<div class="zepp-preview-heading"><strong>${esc(recipe.name)}</strong><span>${fmtDate(recipe.date,{day:'numeric',month:'long',year:'numeric'})}</span></div>${recipe.steps.map((step,i)=>`<div class="zepp-step"><b>${i+1}</b><div><strong>${step.name}</strong><span>${step.durationType===0?step.value/60000+' min':number(recipe.km)+' km'} · ${session.workout?esc(step.notes):step.durationType===1?(session.generated?'Alvo livre':'Conversa confortável'):'Bem leve'}</span></div></div>`).join('')}<p class="field-help">Esforço livre, sem alvo fixo de ritmo ou frequência cardíaca.</p>${session.generated?`<div class="notice"><strong>Orientações do plano · RPE ${session.rpe}/10</strong><p>${esc(session.instructions)}</p><p>${session.workout?'O roteiro preserva os blocos do plano. Os campos de aquecimento extra ficam desativados.':'O arquivo e as etapas representam a distância principal. Consulte estas orientações para executar as variações do treino.'}</p></div>`:''}`;$('#zepp-status').textContent='Use estas etapas para criar o modelo no Zepp. A preparação do roteiro não envia o treino ao relógio.';for(const button of $('#info-dialog').querySelectorAll('[data-action="zepp-download"],[data-action="zepp-share"],[data-action="zepp-copy"],[data-action="zepp-text"]'))button.disabled=false;}catch(error){$('#zepp-preview').textContent=error.message;for(const button of $('#info-dialog').querySelectorAll('[data-action="zepp-download"],[data-action="zepp-share"],[data-action="zepp-copy"],[data-action="zepp-text"]'))button.disabled=true;}}
function selectedZeppFile(){const {session,options}=zeppSelection();return exportWorkoutFit(session,options);}
function downloadZepp(){try{const fit=selectedZeppFile();download(fit.bytes,fit.filename,'application/octet-stream');$('#zepp-status').textContent=`Arquivo preparado: ${fit.filename}. Na sua conexão atual, importar este FIT não sincroniza um treino planejado com o Active 2.`;toast('Arquivo FIT preparado.');}catch(error){toast(error.message);}}
function downloadZeppText(){try{const {session,options}=zeppSelection();const text=workoutInstructions(session,options)+(session.generated?`\n\nOrientações do plano: ${session.minutes} min; RPE ${session.rpe}/10.\n${session.instructions}\n${session.workout?'As etapas preservam os tempos, repetições e recuperações do plano.':'As etapas representam somente a distância principal. Consulte as orientações completas.'}`:'')+'\n\nConfigure estas etapas manualmente no Zepp: Treino > Mais > Modelo de treino > Corrida ao ar livre. Salve e sincronize o modelo com o Active 2.\n';download(text,`dez-voltas-${session.date}-${session.km}km-zepp.txt`,'text/plain;charset=utf-8');$('#zepp-status').textContent='Roteiro preparado. Consulte as etapas ao configurar o modelo manualmente no Zepp.';toast('Roteiro de treino preparado.');}catch(error){toast(error.message);}}
async function shareZepp(){try{const fit=selectedZeppFile();const file=new File([fit.bytes],fit.filename,{type:'application/octet-stream'});if(!navigator.canShare?.({files:[file]})){downloadZepp();return;}await navigator.share({files:[file],title:fit.name});$('#zepp-status').textContent='Arquivo FIT compartilhado. Isso não envia um treino planejado ao seu Active 2 pela conexão atual.';}catch(error){if(error.name!=='AbortError'){$('#zepp-status').textContent='Não foi possível compartilhar neste navegador. Use “Baixar FIT” para salvar o arquivo.';}}}
async function copyZepp(){try{const {session,options}=zeppSelection();const text=workoutInstructions(session,options)+(session.generated?`\n\nOrientações do plano: ${session.minutes} min; RPE ${session.rpe}/10.\n${session.instructions}\n${session.workout?'As etapas preservam os tempos, repetições e recuperações do plano.':'As etapas representam somente a distância principal. Consulte as orientações completas.'}`:'');if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);$('#zepp-status').textContent='Instruções copiadas. Use-as como referência para configurar um modelo manual no Zepp.';toast('Instruções copiadas.');return;}catch{}}$('#zepp-preview').innerHTML='<label class="field">Selecione e copie as instruções<textarea id="zepp-copy-text" readonly rows="10"></textarea></label>';const area=$('#zepp-copy-text');area.value=text;area.focus();area.select();$('#zepp-status').textContent='Mantenha o texto pressionado e escolha Copiar, ou use o comando de cópia do seu dispositivo.';}catch(error){toast(error.message);}}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;switch(action){case'session':openSession(el.dataset.id);break;case'zepp':openZepp(el.dataset.id);break;case'zepp-help':{const id=scheduledSessions().find(s=>s.date>=today())?.id||scheduledSessions().at(-1)?.id;if(id)openZepp(id);else toast('Adote um plano no Perfil para consultar as sessões.');break;}case'zepp-download':downloadZepp();break;case'zepp-text':downloadZeppText();break;case'zepp-share':await shareZepp();break;case'zepp-copy':await copyZepp();break;case'close-session':$('#session-dialog').close();sessionId=null;break;case'close-info':$('#info-dialog').close();break;case'select-day':selectedSession=el.dataset.id;render();break;case'rest-day':openInfo('Espaço para recuperar.',`<p class="modal-intro">${fmtDate(el.dataset.id,{weekday:'long',day:'numeric',month:'long'})}: dia sem corrida programada. Descanse e observe sua recuperação. Se já estiver adaptado, uma sessão leve de força pode entrar conforme a sua rotina.</p><a href="#guia" class="primary" data-action="guide-close">Ver orientações ${icon('arrow',14)}</a>`);break;case'guide-close':$('#info-dialog').close();break;case'previous-week':dashboardWeek=Math.max(1,dashboardWeek-1);selectedSession=knownSessions().find(s=>s.week===dashboardWeek).id;render();break;case'original-plan':try{useOriginalPlan();render();toast('Plano desativado. Seu histórico foi preservado.');}catch{toast('Não foi possível salvar a seleção. Exporte um backup antes de sair.');}break;case'next-week':dashboardWeek=Math.min(8,dashboardWeek+1);selectedSession=knownSessions().find(s=>s.week===dashboardWeek).id;render();break;case'settings':settings();break;case'install':await install();break;case'timer-toggle':toggleTimer();break;case'timer-use':if(state.timer?.id!==sessionId||timerElapsed()<6000){toast('Inicie o cronômetro ou preencha a duração manualmente.');break;}$('#duration-field').value=(timerElapsed()/60000).toFixed(1);toast('Tempo colocado no registro.');break;case'export-json':exportJSON();break;case'export-csv':exportCSV();break;case'import-json':$('#import-file').click();break;case'ics':exportICS();break;case'confirm-import':{const clean=pendingImport;if(!clean)break;try{if(pendingPlanArchive)mergePlanArchive(pendingPlanArchive);}catch{toast('Não foi possível restaurar os planos. Libere espaço e tente novamente.');break;}pendingImport=null;pendingPlanArchive=null;state.logs={...state.logs,...clean.logs};state.checklist={...state.checklist,...clean.checklist};const ok=save();$('#info-dialog').close();render();toast(ok?'Backup restaurado neste navegador.':'Backup aberto, mas ainda não foi possível salvá-lo.');break;}}});
document.addEventListener('submit',e=>{if(e.target.id!=='log-form')return;e.preventDefault();const s=knownSessions().find(x=>x.id===sessionId);if(!s)return;const form=new FormData(e.target);const km=Number(form.get('km')),minutes=Number(form.get('minutes')),rpe=Number(form.get('rpe')),pain=String(form.get('pain'));if(!Number.isFinite(km)||km<0||(!s.generated&&km===0)||km>150||!Number.isFinite(minutes)||minutes<=0||minutes>1440||!Number.isInteger(rpe)||rpe<1||rpe>10){$('#log-feedback').textContent='Confira distância, duração e esforço antes de salvar.';return;}if(s.date>today()){$('#log-feedback').textContent='Esta sessão está programada para uma data futura. Registre-a na data do treino.';return;}state.logs[s.id]={km,minutes,rpe,pain,notes:String(form.get('notes')||'').slice(0,1500),date:s.date,updatedAt:new Date().toISOString()};if(state.timer?.id===s.id&&state.timer.running){state.timer.elapsed=timerElapsed();state.timer.running=false;}const ok=save();$('#session-dialog').close();sessionId=null;render();toast(ok?'Treino registrado. Uma volta de cada vez.':'Registro em memória. Exporte um backup antes de sair.');});
document.addEventListener('input',e=>{if(e.target.id==='lap-minutes')updateLap();if(e.target.id==='zepp-warmup'||e.target.id==='zepp-cooldown')updateZeppPreview();});
document.addEventListener('change',e=>{if(e.target.id==='zepp-select'){zeppSessionId=e.target.value;updateZeppPreview();}if(e.target.matches('[data-check]')){state.checklist[e.target.dataset.check]=e.target.checked;save();updateChecklist();}});
let pendingImport=null,pendingPlanArchive=null;
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Arquivo grande demais.');const raw=JSON.parse(await file.text());if(raw.version!==1||raw.app!=='dez-voltas')throw new Error('Escolha um backup do Dez Voltas.');pendingPlanArchive=raw.generatedPlans?validatePlanArchive(raw.generatedPlans):null;pendingImport=cleanState(raw,pendingPlanArchive?allGeneratedSessions(pendingPlanArchive):[]);const count=Object.keys(pendingImport.logs).length;openInfo('Restaurar este backup?',`<p class="modal-intro">O arquivo contém <strong>${count} registro(s)</strong>. Os treinos com a mesma identificação serão substituídos pelos registros do arquivo. Os demais serão mantidos.</p><div class="form-actions"><button class="secondary" data-action="close-info">Cancelar</button><button class="primary" data-action="confirm-import">Restaurar backup</button></div>`);}catch(err){toast('Não foi possível importar: '+err.message);}finally{e.target.value='';}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
window.addEventListener('online',connection);window.addEventListener('offline',connection);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('Dez Voltas instalado. Bons treinos!');});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('#settings-button').innerHTML=icon('settings',17);$('.install-button').innerHTML=icon('download',16)+' Instalar no celular';$('#header-date').textContent=fmtDate(today(),{weekday:'long',day:'numeric',month:'long'});
render();connection();setInterval(updateTimer,500);
async function offline(){if(!('serviceWorker' in navigator)){$('#offline-status').textContent='Acesso offline indisponível neste navegador';return;}try{await navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'});await navigator.serviceWorker.ready;$('#offline-status').textContent='Plano disponível offline';}catch{$('#offline-status').textContent='Offline ainda indisponível · tente recarregar online';}}
offline();

window.addEventListener('weekly-review-change',()=>{if(location.hash==='#plano')render();});
window.addEventListener('profile-change',()=>{const actions=document.querySelector('#account-actions');if(actions)actions.innerHTML=renderAccountActions();if(location.hash==='#perfil'||needsRegistration())render();});
window.addEventListener('active-plan-change',()=>{if(location.hash!=='#perfil')render();});
configureAccountSync({
 capture(owner){const archive=exportPlanArchive();const owned=archive.plans.filter(p=>p.owner===owner),ids=new Set([...SESSIONS,...allGeneratedSessions({plans:owned})].map(s=>s.id));return {version:1,draft:JSON.parse(localStorage.getItem('dez-voltas-draft-v1:'+owner)||'null'),profile:JSON.parse(localStorage.getItem('dez-voltas-profile-v1:'+owner)||'null'),archive:{version:1,owner,plans:owned},state:{...state,logs:Object.fromEntries(Object.entries(state.logs).filter(([id])=>ids.has(id))),timer:null}};},
 select(owner,saved){
  const marker=localStorage.getItem('dez-voltas-legacy-owner');
  if(!marker){localStorage.setItem('dez-voltas-legacy-backup',JSON.stringify({state,archive:exportPlanArchive()}));localStorage.setItem('dez-voltas-legacy-owner',owner);}
  if(saved)this.apply(saved,owner);
  else if(marker&&marker!==owner){state={version:1,logs:{},checklist:{},timer:null};localStorage.setItem(KEY,JSON.stringify(state));}
  else {const allowed=new Set([...SESSIONS,...allGeneratedSessions({plans:exportPlanArchive().plans.filter(p=>p.owner===owner)})].map(s=>s.id));state={...state,logs:Object.fromEntries(Object.entries(state.logs).filter(([id])=>allowed.has(id))),timer:null};}
 },
 apply(doc,owner){
  replaceOwnerArchive(owner,doc.archive);state=cleanState(doc.state);localStorage.setItem(KEY,JSON.stringify(state));
  const dk='dez-voltas-draft-v1:'+owner;if(doc.draft)localStorage.setItem(dk,JSON.stringify(doc.draft));else localStorage.removeItem(dk);
  const k='dez-voltas-profile-v1:'+owner;if(doc.profile)localStorage.setItem(k,JSON.stringify(doc.profile));else localStorage.removeItem(k);
  window.dispatchEvent(new Event('account-data-loaded'));window.dispatchEvent(new Event('active-plan-change'));
 },
 disconnect(){state={version:1,logs:{},checklist:{},timer:null};localStorage.setItem(KEY,JSON.stringify(state));window.dispatchEvent(new Event('active-plan-change'));}
});
resumeAccountSync();
initWeeklyReview();
initProfile();
